  justify-content: space-between;
  padding-bottom: 10px;
}
.vbi-licence-modal .copy-rights {
  text-align: right;
  width: 30%;
  padding: 0px 5px;
}
.vbi-licence-modal .feedback-link {
  width: 70%;
}
.free-trial-btn {
  margin-top: 5px;
  padding: 8px 8px;
  text-transform: uppercase;
  font-weight: 500;
  text-align: center;
  background: linear-gradient(to right, #eaeaea 50%, #f2c811 50%);
  background-size: 200% 100%;
  background-position: left bottom;
  transition: all 2s ease;
  cursor: pointer;
}
.free-trial-btn:hover {
  background-position: right bottom;
}
.buy-licence {
  padding-top: 5px;
}
.vbi-licence-modal .email-ui input {
  border: 1px solid #efefef;
  width: 100%;
  margin-top: 5px;
  box-sizing: border-box;
  padding: 6px;
}
.flex-container {
  display: flex;
  flex-direction: column;
}
.help-modal::-webkit-scrollbar {
  width: 8px;
}
.help-modal::-webkit-scrollbar-track {
  background-color: #e2e0e0;
}
.help-modal::-webkit-scrollbar-thumb {
  border-radius: 10px;
  background-color: #a0a0a0;
}
/*help modal*/
.help-modal {
  background-color: #ffffff;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  box-shadow: 0 0 20px #bbb;
  width: 430px;
  height: 170px;
  right: 0;
  top: 150px;
  display: none;
  padding: 16px 16px 4px 16px;
  color: #333333;
  box-sizing: border-box;
}
.help-modal .header {
  text-align: center;
}
.help-modal-logo {
  width: 55px;
  height: 18px;
}
.xviz-icon-full {
  background-repeat: no-repeat;
  background-size: cover;
  background-image: url('data:image/svg+xml;base64,');
}
.help-modal h3 {
  font-size: 18px;
  font-weight: 400 !important;
  padding-left: 15px;
  margin: 0;
}
.ratings {
  display: inline;
}
.help-modal .close-modal {
  position: absolute;
  right: 16px;
  top: 16px;
  cursor: pointer;
  font-size: 14px;
  width: 20px;
  height: 20px;
  background-image: url('data:image/svg+xml;base64,');
}
.section {
  float: left;
  width: 33.33%;
}
.section .section-label {
  font-size: 14px;
  line-height: 14px;
  text-transform: uppercase !important;
  font-weight: 500 !important;
}
.help-link {
  display: block;
  font-size: 12px;
  text-decoration: none;
  box-shadow: none !important;
  color: #333333;
  line-height: 24px;
}
a.help-link:visited,
a.help-link:active,
a.help-link:focus {
  color: #333;
}
a.help-link:hover {
  color: #194a9f;
  text-decoration: none;
}
.licence-section {
  font-size: 12px;
  box-shadow: none !important;
  color: #333333;
}
.modal-footer {
  border-top: 1px solid #eaeaea;
  margin-top: 14px;
}
.modal-footer > p {
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
  overflow: hidden;
  font-weight: 400 !important;
  display: inline-block;
  width: 50%;
  cursor: default;
}
.copyright {
  text-align: right;
}
.bold {
  font-weight: bold;
}
.vbi-licence-body,
.modal-footer {
  float: left;
  width: 100%;
}
.help-modal {
  float: left;
}
@media (max-width: 480px) {
  .help-modal {
    width: 100%;
    overflow-x: auto;
  }
  .section,
  .modal-footer > p {
    width: 100%;
  }
  .modal-footer > p {
    margin-bottom: 0;
  }
  .modal-footer .copyright {
    text-align: left;
  }
}
@media (max-height: 230px) {
  .help-modal {
    overflow-y: scroll !important;
    height: 75px !important;
  }
}
@media (max-width: 230px) {
  .help-modal {
    width: 150px !important;
  }
  .vbi-licence-modal .vbi-licence-body p {
    font-size: 10px !important;
  }
}
