/* 
  Landing Page CSS
*/
.landing-page-wrapper {
  position: absolute;
  top: 0;
  max-width: 100vw;
  left: 0;
  width: 100vw;
  height: 100vh;
  z-index: 100000000;
  overflow: hidden;
  box-sizing: border-box;
  display: grid;
  grid-template-rows: auto auto auto;
}
.landing-background-overlay {
  width: 100%;
  height: 100%;
  position: absolute;
  background: white;
  opacity: 0.75;
  top: 0;
  left: 0;
  z-index: -1;
}
.landing-page-header {
  width: 100%;
  max-width: 100vw;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 25px 0 25px;
  flex-wrap: wrap;
}
.landing-page-header > img {
  height: 70px;
}
.landing-page-header > h2 {
  font-weight: 450;
  font-size: 32px;
}
.landing-page-body {
  width: 100%;
  max-width: 100vw;
  display: flex;
  align-items: center;
  justify-content: space-around;
  flex-direction: column;
}
.landing-page-body .warning-message {
  margin: 0.2rem 0.5rem;
  padding: 0.3rem 1rem 0.3rem 1rem;
  background-color: #FED9CC;
  color: #201F1E;
  text-align: center;
}
.landing-page-button {
  outline: none;
  text-align: center;
  width: 180px;
  padding: 10px 0 10px 0;
  font-size: 1em;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 5px;
  box-shadow: 0 0 3px 0 gray;
  text-decoration: none !important;
  color: black !important;
}
.landing-page-button:visited,
.landing-page-button:active,
.landing-page-button:hover {
  text-decoration: none !important;
  color: black !important;
}
.landing-page-button:hover {
  opacity: 0.8;
}
.landing-page-footer {
  width: 100%;
  max-width: 100vw;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  padding: 0 10px 0 10px;
}
.landing-page-footer > p {
  font-weight: 500;
  text-align: center;
}
.landing-page-footer > p > a {
  text-decoration: none;
  color: #1e7ce9;
  white-space: nowrap;
}
.landing-page-footer-chart-showcase-wrapper {
  display: flex;
  flex-direction: row;
  box-sizing: border-box;
}
.footer-chart-showcase {
  width: 150px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
}
.footer-chart-showcase > img {
  height: 70px;
}
.footer-chart-showcase > p {
  font-size: 14px;
  margin-top: -7px;
}
.bg-yellow {
  background: #f2c811;
}
.bg-gray {
  background: #f4f4f4;
}
@media only screen and (max-width: 700px) {
  .footer-chart-showcase:nth-child(2n) {
    display: none;
  }
  .landing-page-header > img {
    height: 50px;
  }
  .landing-page-header > h2 {
    font-size: 22px;
  }
  .landing-page-button {
    width: 140px;
  }
  .landing-page-footer {
    font-size: 16px;
  }
  .footer-chart-showcase > img {
    height: 50px;
  }
  .footer-chart-showcase > p {
    font-size: 12px;
    margin-top: -7px;
  }
}
@media only screen and (max-width: 400px) {
  .header {
    padding: 0 10px 0 10px;
  }
  .landing-page-body .warning-message {
    font-size: 14px;
  }
  .landing-page-footer {
    display: none;
  }
  .footer-chart-showcase {
    display: none;
  }
  .landing-page-header > img {
    height: 30px;
  }
  .landing-page-header > h2 {
    font-size: 18px;
  }
  .landing-page-button {
    width: 120px;
    padding: 9px 0 9px 0;
    font-size: 15px;
  }
  .landing-page-footer {
    font-size: 14px;
  }
}
@media only screen and (max-height: 300px) {
  .landing-page-body .warning-message {
    font-size: 12px;
  }
  .landing-page-footer {
    display: none;
  }
  .footer-chart-showcase {
    display: none;
  }
  .landing-page-button {
    width: 110px;
    padding: 8px 0 8px 0;
    font-size: 14px;
  }
  .landing-page-header > img {
    height: 30px;
  }
  .landing-page-header > h2 {
    font-size: 17px;
  }
}
@media only screen and (max-height: 200px) {
  .landing-page-body .warning-message {
    font-size: 12px;
  }
  .landing-page-footer {
    display: none;
  }
  .landing-page-button {
    width: 110px;
    padding: 6px 0 6px 0;
    font-size: 14px;
  }
  .landing-page-header > img {
    height: 30px;
  }
  .landing-page-header > h2 {
    font-size: 15px;
  }
}
#vbi-fetching-indicator {
  display: flex;
  width: fit-content;
  color: #fff;
  background: #111;
  padding: 3px 6px;
}
#vbi-fetching-indicator > .error-span {
