/** Pro Property**/
.proContainer {
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  position: fixed;
  right: 0;
  width: auto;
  height: auto;
  float: left;
  background-color: #fff;
  border-radius: 3px;
  box-shadow: 0px 0px 11px -1px #a6a6a6;
  padding: 15px;
  margin: 2px 5px 10px 10px;
  z-index: 1;
  box-sizing: border-box;
}
.proContainer h4 {
  font-weight: 400;
  color: #333;
  margin: 10px 0;
  font-size: 16px;
}
.proContainer p {
  margin: 0 0 15px 0;
  font-size: 12px;
  color: #333;
}
.proContainer p span {
  font-weight: 600;
}
.proInfo {
  clear: both;
  float: left;
  color: #0078D4;
  margin-top: 10px;
  text-decoration: none;
  font-size: 12px;
  font-weight: 600;
}
.pro_xvizLogo {
  width: 90px;
  height: 30px;
}
.proPurchase {
  width: 150px;
  float: left;
  height: 30px;
  font-size: 13px;
  text-decoration: none;
  text-align: center;
  line-height: 30px;
  font-weight: 600;
  color: #333;
}
.propuchase_btn {
  background: #f2c811;
  color: #000;
  font-size: 12px;
  font-weight: 500;
  max-width: 150px;
  padding: 6px 14px;
  float: left;
  text-align: center;
}
a.propuchase_btn,
a.proInfo {
  text-decoration: none;
}
a.propuchase_btn:focus,
a.propuchase_btn a:hover,
a.propuchase_btn:active,
a.propuchase_btn.active,
a.propuchase_btn:visited {
  color: #000 !important;
}
a.proInfo:focus,
a.proInfo a:hover,
a.proInfo:active,
a.proInfo.active,
a.proInfo:visited {
  color: #0078D4 !important;
}
@media only screen and (max-width: 150px) and (max-height: 550px) {
  .proContainer {
    width: 80%;
    overflow-y: scroll;
    height: 300px;
  }
}
@media only screen and (min-width: 400px) {
  .proContainer {
    width: 300px;
  }
}
@media only screen and (max-height: 250px) and (max-width: 250px) {
  .proContainer {
    height: calc(100% - 20px);
    overflow-y: auto;
  }
  .propuchase_btn {
    width: auto;
    text-align: left;
  }
}
@media only screen and (max-width: 200px) and (max-height: 320px) {
  .proContainer {
    overflow-y: scroll;
    width: 80%;
    height: calc(100% - 20px);
  }
}
@media only screen and (max-width: 120px) {
  .proContainer {
    height: calc(100% - 20px);
    overflow-y: auto;
    width: 90% !important;
  }
}
